# ntllm gzip+kNN kernel, mode=submit. Fit set: train (splits v1).

"""Gzip + kNN classifier using normalized compression distance (NCD).

    NCD(x, y) = (C(x+y) - min(C(x), C(y))) / max(C(x), C(y)),   C = gzip-compressed length

Stdlib + numpy only: the Kaggle notebook inlines this file unchanged.
No training: fit() just stores the training texts and their compressed lengths.
"""
import gzip
import os
from multiprocessing import get_context

import numpy as np

SEP = b" "


def clen(b: bytes, level: int) -> int:
    # mtime=0 keeps the gzip header fixed so lengths are deterministic.
    return len(gzip.compress(b, compresslevel=level, mtime=0))


# Worker state, set once per process by the pool initializer.
_W = {}


def _init_worker(train_bytes, train_clen, level):
    _W["train"], _W["tlen"], _W["level"] = train_bytes, train_clen, level


def _ncd_chunk(chunk):
    train, tlen, level = _W["train"], _W["tlen"], _W["level"]
    out = np.empty((len(chunk), len(train)), dtype=np.float32)
    for i, x in enumerate(chunk):
        cx = clen(x, level)
        for j, y in enumerate(train):
            cy = tlen[j]
            out[i, j] = (clen(x + SEP + y, level) - min(cx, cy)) / max(cx, cy)
    return out


class GzipKNN:
    def __init__(self, k: int = 1, level: int = 9, n_jobs: int | None = None, chunk: int = 8):
        self.k, self.level, self.chunk = k, level, chunk
        self.n_jobs = n_jobs or os.cpu_count() or 1

    def fit(self, texts, labels):
        self.train_ = [t.encode("utf-8") for t in texts]
        self.labels_ = np.asarray(labels)
        self.classes_ = np.array(sorted(set(self.labels_)))
        self.train_clen_ = [clen(b, self.level) for b in self.train_]
        return self

    def distances(self, texts) -> np.ndarray:
        """NCD matrix, shape (len(texts), n_train). The expensive part."""
        xs = [t.encode("utf-8") for t in texts]
        chunks = [xs[i:i + self.chunk] for i in range(0, len(xs), self.chunk)]
        args = (self.train_, self.train_clen_, self.level)
        if self.n_jobs == 1:
            _init_worker(*args)
            parts = [_ncd_chunk(c) for c in chunks]
        else:
            with get_context().Pool(self.n_jobs, initializer=_init_worker, initargs=args) as pool:
                parts = pool.map(_ncd_chunk, chunks)
        return np.vstack(parts) if parts else np.empty((0, len(self.train_)), np.float32)

    def predict_from_distances(self, D: np.ndarray, k: int | None = None) -> np.ndarray:
        """Majority vote over the k nearest; ties go to the label whose neighbor came first."""
        k = k or self.k
        nearest = np.argsort(D, axis=1, kind="stable")[:, :k]
        preds = []
        for row in nearest:
            counts, best, best_n = {}, None, 0
            for j in row:
                lab = self.labels_[j]
                counts[lab] = counts.get(lab, 0) + 1
                if counts[lab] > best_n:  # strict >: earlier (closer) label wins ties
                    best, best_n = lab, counts[lab]
            preds.append(best)
        return np.array(preds)

    def class_min_distance(self, D: np.ndarray) -> np.ndarray:
        """Per-class nearest distance, shape (n, n_classes) in classes_ order. Blend feature."""
        return np.stack([D[:, self.labels_ == c].min(axis=1) for c in self.classes_], axis=1)

    def predict(self, texts) -> np.ndarray:
        return self.predict_from_distances(self.distances(texts))


# ---------------------------------------------------------------- config
MODE = 'submit'
FIT_ON = 'train'
K = 1
LEVEL = 9
DUMMY_ROWS = 4000
LABELS = ['claude-fable-5', 'claude-opus-4-6', 'claude-opus-4-8', 'claude-opus-5', 'claude-sonnet-5', 'gemini-3.1-pro-preview', 'gemini-3.6-flash', 'gemini-3.7-flash', 'gemini-3.8-flash', 'glm-5.3', 'glm-5.3-flash', 'gpt-5.5', 'gpt-5.6-luna', 'gpt-5.6-sol', 'gpt-5.6-terra', 'gpt-6-astra', 'kimi-k3', 'qwen3.8-max']
TRAIN_PROMPTS = ['p001', 'p006', 'p008', 'p009', 'p010', 'p011', 'p014', 'p015', 'p016', 'p017', 'p019', 'p021', 'p022', 'p023', 'p026', 'p029', 'p030', 'p031', 'p032', 'p034', 'p035', 'p036', 'p038', 'p039', 'p040', 'p041', 'p042', 'p043', 'p044', 'p047', 'p048', 'p049', 'p053', 'p055', 'p057', 'p058', 'p059', 'p060', 'p061', 'p062', 'p063', 'p064', 'p065', 'p067', 'p069', 'p071', 'p072', 'p074', 'p075', 'p076', 'p077', 'p080', 'p083', 'p084', 'p088', 'p092', 'p093', 'p095', 'p097', 'p098', 'p099', 'p100', 'p102', 'p104', 'p107', 'p108', 'p109', 'p110', 'p112', 'p113', 'p115', 'p117', 'p118', 'p119', 'p121', 'p127', 'p128', 'p132', 'p133', 'p136', 'p137', 'p138', 'p139', 'p140', 'p141', 'p142', 'p145', 'p147', 'p148', 'p149']


# ---------------------------------------------------------------- kernel main
import glob
import time

import pandas as pd

INPUT = os.environ.get("NTLLM_INPUT", "/kaggle/input")
OUTPUT = os.environ.get("NTLLM_OUTPUT", "/kaggle/working")


def find(name):
    hits = sorted(glob.glob(os.path.join(INPUT, "**", name), recursive=True))
    assert hits, f"{name} not found under {INPUT}"
    return hits[0]


def main():
    t0 = time.time()
    full = pd.read_csv(find("train.csv"))
    train = full[full.prompt_id.isin(TRAIN_PROMPTS)] if FIT_ON == "train" else full
    assert FIT_ON == "all" or train.prompt_id.nunique() == len(TRAIN_PROMPTS)

    if MODE == "timing":
        # Dummy test the size of the hidden one, drawn from passages outside the fit set.
        pool = full[~full.id.isin(train.id)] if FIT_ON == "train" else full
        test = pool.sample(n=DUMMY_ROWS, replace=True, random_state=0)[["text"]].reset_index(drop=True)
        test.insert(0, "id", [f"dummy{i:05d}" for i in range(len(test))])
    else:
        test = pd.read_csv(find("test.csv"))
    print(f"mode={MODE} fit_on={FIT_ON} k={K} level={LEVEL} cpus={os.cpu_count()} "
          f"train={len(train)} test={len(test)}", flush=True)

    model = GzipKNN(k=K, level=LEVEL).fit(train.text.tolist(), train.model.tolist())
    t1 = time.time()
    preds = model.predict(test.text.tolist())
    t2 = time.time()

    sub = pd.DataFrame({"id": test.id, "model": preds})
    assert sub.id.is_unique and set(sub.id) == set(test.id)
    assert set(sub.model) <= set(LABELS), set(sub.model) - set(LABELS)
    name = "submission.parquet" if MODE == "submit" else "timing_submission.parquet"
    os.makedirs(OUTPUT, exist_ok=True)
    sub.to_parquet(os.path.join(OUTPUT, name), index=False)

    per_row = (t2 - t1) / max(len(test), 1)
    print(f"fit {t1 - t0:.1f}s  predict {t2 - t1:.1f}s  ({per_row * 1000:.1f} ms/row)  "
          f"total {time.time() - t0:.1f}s", flush=True)
    print(f"projected for 4,000 rows: {per_row * 4000 / 60:.1f} min (limit 540 min)", flush=True)
    print(f"wrote {name}: {len(sub)} rows, {sub.model.nunique()} labels predicted", flush=True)


if __name__ == "__main__":
    main()
